export const PROMPT_QUESTIONS=[
'Hôm nay bạn muốn làm gì?','Bạn đang muốn sáng tạo gì?','Bạn muốn biến ý tưởng nào thành hình ảnh?','Một khung hình trong mơ của bạn trông thế nào?','Bạn muốn kể câu chuyện gì bằng hình ảnh?','Hôm nay bạn muốn khám phá phong cách nào?','Bạn muốn thử một góc nhìn mới chứ?','Bạn đang hình dung một nhân vật như thế nào?','Sản phẩm của bạn sẽ xuất hiện ở đâu?','Bạn muốn tạo một thế giới như thế nào?','Ánh sáng nào phù hợp với ý tưởng của bạn?','Bạn muốn bắt đầu từ một bức ảnh chứ?','Bạn muốn thay đổi điều gì trong ảnh?','Một bối cảnh điện ảnh của bạn sẽ ra sao?','Bạn muốn chuyển ý tưởng nào thành video?','Điều gì sẽ chuyển động trong khung hình?','Bạn muốn thử một bảng màu mới chứ?','Bạn đang tìm cảm hứng cho thiết kế nào?','Bạn muốn tạo hình ảnh chủ đạo như thế nào?','Một chân dung theo cách của bạn sẽ ra sao?','Bạn muốn đưa sản phẩm vào không gian nào?','Bạn muốn biến bản phác thảo thành gì?','Khoảnh khắc nào bạn muốn tái hiện?','Bạn muốn thử chất liệu nào hôm nay?','Bạn muốn khám phá một bố cục khác chứ?','Một thế giới tương lai của bạn sẽ ra sao?','Bạn muốn giữ lại cảm xúc nào trong ảnh?','Bạn muốn làm mới hình ảnh nào?','Ý tưởng táo bạo nhất của bạn là gì?','Chúng ta bắt đầu từ ý tưởng nào?'];
export function createPromptHintHook(React){const{useState:S,useEffect:E}=React;return function usePromptHint(paused){const[text,TEXT]=S(PROMPT_QUESTIONS[0]);E(()=>{const reduced=matchMedia('(prefers-reduced-motion: reduce)');let timer,dead=false,index=0,position=0,phase='hold',ticks=0;const chars='01<>/[]_';function schedule(ms){timer=setTimeout(step,ms)}function step(){if(dead)return;if(document.hidden){schedule(500);return}const phrase=PROMPT_QUESTIONS[index];if(phase==='hold'){phase='erase';position=phrase.length;schedule(2800);return}if(phase==='erase'){position=Math.max(0,position-3);TEXT(phrase.slice(0,position));if(position===0){index=(index+1)%PROMPT_QUESTIONS.length;phase='decode';ticks=0}schedule(24);return}if(phase==='decode'){ticks++;TEXT(Array.from({length:Math.min(7,ticks+2)},()=>chars[Math.floor(Math.random()*chars.length)]).join(''));if(ticks>=5){phase='type';position=0}schedule(45);return}position++;TEXT(phrase.slice(0,position)+(position<phrase.length?chars[Math.floor(Math.random()*chars.length)]:''));if(position>=phrase.length){phase='hold';schedule(100)}else schedule(42)}function sync(){clearTimeout(timer);TEXT(PROMPT_QUESTIONS[0]);index=0;phase='hold';if(!paused&&!reduced.matches)schedule(0)}sync();reduced.addEventListener('change',sync);return()=>{dead=true;clearTimeout(timer);reduced.removeEventListener('change',sync)}},[paused]);return text}}
